// ============================================================
// ANALYZER
// ============================================================

function Analyzer({ analysis }) {
  const [capital, setCapital] = useState(1000);
  const [riskBudget, setRiskBudget] = useState(50);
  const [target, setTarget] = useState(200);
  const [probability, setProbability] = useState(58);
  const [odds, setOdds] = useState(2);
  const [maxLoss, setMaxLoss] = useState(35);
  const [volatility, setVolatility] = useState(5);
  const [confidence, setConfidence] = useState(72);
  const [agreement, setAgreement] = useState(76);

  const currentAnalysis = useMemo(() => {
    return analyzeSetup({
      probability,
      decimalOdds: odds,
      maxLoss,
      riskBudget,
      volatility,
      confidence,
      modelAgreement: agreement,
    });
  }, [
    probability,
    odds,
    maxLoss,
    riskBudget,
    volatility,
    confidence,
    agreement,
  ]);

  const simulation = useMemo(() => {
    return monteCarlo({
      probability: probability / 100,
      winReturn: Math.max(
        0.01,
        (target - maxLoss) /
          Math.max(capital, 1)
      ),
      lossReturn:
        -maxLoss /
        Math.max(capital, 1),
      bankroll: capital,
      trials: 2500,
    });
  }, [
    probability,
    target,
    maxLoss,
    capital,
  ]);

  return (
    <main className="page">
      <section className="section-heading">
        <div>
          <div className="eyebrow">
            <BrainCircuit size={15} />
            ANALYSIS WORKSPACE
          </div>

          <h2>
            Test an opportunity before
            <span> risking capital.</span>
          </h2>

          <p>
            Enter hypothetical assumptions and let the
            engine examine probability, expected value,
            volatility, confidence, and risk exposure.
          </p>
        </div>

        <div className="analysis-score">
          <span>ENGINE SCORE</span>

          <strong>
            {currentAnalysis.score}
          </strong>

          <small>/100</small>
        </div>
      </section>

      <section className="analysis-layout">
        <div className="input-panel">
          <div className="panel-heading">
            <div>
              <span className="panel-kicker">
                INPUTS
              </span>

              <h3>
                Opportunity Parameters
              </h3>
            </div>

            <CircleDollarSign size={22} />
          </div>

          <div className="input-grid">
            <NumberInput
              label="Starting Capital"
              value={capital}
              setValue={setCapital}
              prefix="$"
            />

            <NumberInput
              label="Risk Budget"
              value={riskBudget}
              setValue={setRiskBudget}
              prefix="$"
            />

            <NumberInput
              label="Potential Target"
              value={target}
              setValue={setTarget}
              prefix="$"
            />

            <NumberInput
              label="Estimated Probability"
              value={probability}
              setValue={setProbability}
              suffix="%"
            />

            <NumberInput
              label="Decimal Payoff"
              value={odds}
              setValue={setOdds}
              step="0.1"
            />

            <NumberInput
              label="Maximum Loss"
              value={maxLoss}
              setValue={setMaxLoss}
              prefix="$"
            />

            <NumberInput
              label="Volatility"
              value={volatility}
              setValue={setVolatility}
              suffix="%"
            />

            <NumberInput
              label="Confidence"
              value={confidence}
              setValue={setConfidence}
              suffix="%"
            />

            <NumberInput
              label="Model Agreement"
              value={agreement}
              setValue={setAgreement}
              suffix="%"
            />
          </div>

          <div className="input-note">
            <AlertTriangle size={15} />

            All inputs are hypothetical and are used
            only for educational analysis.
          </div>
        </div>

        <div className="decision-panel">
          <div className="decision-top">
            <span className="panel-kicker">
              AI DECISION ENGINE
            </span>

            <div
              className={`decision-badge ${
                currentAnalysis.label.toLowerCase()
              }`}
            >
              {currentAnalysis.label ===
                "REJECTED" && (
                <X size={16} />
              )}

              {currentAnalysis.label ===
                "QUALIFIED" && (
                <CheckCircle2 size={16} />
              )}

              {currentAnalysis.label ===
                "WATCH" && (
                <AlertTriangle size={16} />
              )}

              {currentAnalysis.label}
            </div>
          </div>

          <div className="decision-score">
            <span>
              {currentAnalysis.score}
            </span>

            <small>
              / 100
            </small>
          </div>

          <p className="decision-description">
            {currentAnalysis.label === "REJECTED"
              ? "The engine found at least one condition that violates the current risk or quality rules."
              : currentAnalysis.label ===
                "QUALIFIED"
              ? "The hypothetical setup currently passes the prototype's defined decision rules."
              : "The setup has some positive characteristics, but the engine recommends additional analysis before qualification."}
          </p>

          <div className="decision-stats">
            <DecisionStat
              label="Expected Value"
              value={`${(
                currentAnalysis.expectedValue *
                100
              ).toFixed(2)}%`}
            />

            <DecisionStat
              label="Implied Probability"
              value={`${(
                currentAnalysis.impliedProbability *
                100
              ).toFixed(1)}%`}
            />

            <DecisionStat
              label="Fractional Kelly"
              value={`${(
                currentAnalysis.kellyFraction *
                100
              ).toFixed(2)}%`}
            />
          </div>

          <div className="reason-box">
            <div className="reason-heading">
              <Sparkles size={15} />
              WHY THE ENGINE DECIDED THIS
            </div>

            <div className="reason-list">
              {currentAnalysis.reasons.map(
                (reason, index) => (
                  <div
                    className="reason"
                    key={index}
                  >
                    <span>
                      {index + 1}
                    </span>

                    <p>{reason}</p>
                  </div>
                )
              )}
            </div>
          </div>
        </div>
      </section>

      <section className="simulation-card">
        <div className="panel-heading">
          <div>
            <span className="panel-kicker">
              MONTE CARLO
            </span>

            <h3>
              Hypothetical Outcome Simulation
            </h3>
          </div>

          <LineChart size={22} />
        </div>

        <div className="simulation-grid">
          <SimulationMetric
            label="Average"
            value={`$${simulation.average.toFixed(
              0
            )}`}
          />

          <SimulationMetric
            label="Median"
            value={`$${simulation.median.toFixed(
              0
            )}`}
          />

          <SimulationMetric
            label="5th Percentile"
            value={`$${simulation.worstCase.toFixed(
              0
            )}`}
          />

          <SimulationMetric
            label="95th Percentile"
            value={`$${simulation.bestCase.toFixed(
              0
            )}`}
          />
        </div>
      </section>
    </main>
  );
}

// ============================================================
// NUMBER INPUT
// ============================================================

function NumberInput({
  label,
  value,
  setValue,
  prefix,
  suffix,
  step = "1",
}) {
  return (
    <label className="number-input">
      <span>{label}</span>

      <div className="input-wrapper">
        {prefix && (
          <b>{prefix}</b>
        )}

        <input
          type="number"
          value={value}
          step={step}
          onChange={(event) =>
            setValue(
              Number(event.target.value)
            )
          }
        />

        {suffix && (
          <b>{suffix}</b>
        )}
      </div>
    </label>
  );
}

// ============================================================
// DECISION STAT
// ============================================================

function DecisionStat({
  label,
  value,
}) {
  return (
    <div className="decision-stat">
      <span>{label}</span>

      <strong>{value}</strong>
    </div>
  );
}

// ============================================================
// SIMULATION METRIC
// ============================================================

function SimulationMetric({
  label,
  value,
}) {
  return (
    <div className="simulation-metric">
      <span>{label}</span>

      <strong>{value}</strong>
    </div>
  );
}

